import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './LogsViewer.css';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || 'http://localhost:8001';

const LogsViewer = ({ onClose }) => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lines, setLines] = useState(100);
  const [levelFilter, setLevelFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [error, setError] = useState(null);

  // --- NOVOS ESTADOS PARA DATA/HORA ---
  const [timeRange, setTimeRange] = useState('all'); // 'all', '15m', '30m', '1h', '24h', 'absolute'
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  const intervalRef = useRef(null);
  const logsEndRef = useRef(null);

  const scrollToBottom = () => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const fetchLogs = async () => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams();
      params.append('lines', lines);

      if (levelFilter !== 'all') {
        params.append('level', levelFilter);
      }

      if (searchTerm) {
        params.append('search', searchTerm);
      }

      // --- LÓGICA DE CÁLCULO DE TEMPO ---
      if (timeRange !== 'all') {
        const now = new Date();
        let startDate = null;
        let endDate = null;

        if (timeRange === 'absolute') {
          // Range customizado (usuário escolheu as datas)
          if (customStart) startDate = new Date(customStart);
          if (customEnd) endDate = new Date(customEnd);
        } else {
          // Range relativo (15m, 30m, etc)
          startDate = new Date(now);
          switch (timeRange) {
            case '15m': startDate.setMinutes(now.getMinutes() - 15); break;
            case '30m': startDate.setMinutes(now.getMinutes() - 30); break;
            case '1h': startDate.setHours(now.getHours() - 1); break;
            case '24h': startDate.setHours(now.getHours() - 24); break;
            default: break;
          }
        }

        // Formatar para ISO String (YYYY-MM-DDTHH:mm:ss) para o Backend
        if (startDate) params.append('start_time', startDate.toISOString().split('.')[0]); // Remove ms
        if (endDate) params.append('end_time', endDate.toISOString().split('.')[0]);
      }

      // Add /api if not already present
      const baseUrl = BACKEND_URL.includes('/api') ? BACKEND_URL : `${BACKEND_URL}/api`;
      const response = await axios.get(`${baseUrl}/logs?${params}`);

      if (response.data.error) {
        setError(response.data.error);
      } else {
        // Se usar filtro de tempo, o backend pode mandar na ordem original, 
        // invertemos aqui para mostrar o mais recente embaixo se for log streaming, 
        // ou em cima se for lista estática. 
        // Seu código original não invertia, então mantive assim.
        setLogs(response.data.logs || []);
      }
    } catch (err) {
      setError(`Erro ao buscar logs: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Atualiza quando qualquer filtro muda
  useEffect(() => {
    fetchLogs();
  }, [lines, levelFilter, searchTerm, timeRange, customStart, customEnd]); 

  useEffect(() => {
    if (autoRefresh) {
      intervalRef.current = setInterval(() => {
        fetchLogs();
      }, 3000);
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [autoRefresh, lines, levelFilter, searchTerm, timeRange]);

  useEffect(() => {
    if (autoRefresh) {
      scrollToBottom();
    }
  }, [logs, autoRefresh]);

  const getLevelColor = (level) => {
    switch (level?.toLowerCase()) {
      case 'error': return 'log-error';
      case 'warning': return 'log-warning';
      case 'info': return 'log-info';
      case 'debug': return 'log-debug';
      default: return '';
    }
  };

  const getLevelIcon = (level) => {
    switch (level?.toLowerCase()) {
      case 'error': return '❌';
      case 'warning': return '⚠️';
      case 'info': return 'ℹ️';
      case 'debug': return '🔍';
      default: return '📝';
    }
  };

  const downloadLogs = () => {
    const content = logs.map(log => JSON.stringify(log)).join('\n');
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `genexus-logs-${new Date().toISOString()}.log`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const copyToClipboard = (log) => {
    navigator.clipboard.writeText(JSON.stringify(log, null, 2));
  };

  return (
    <div className="logs-viewer-overlay">
      <div className="logs-viewer">
        {/* Header */}
        <div className="logs-header">
          <h2>📊 Application Logs</h2>
          <button className="close-button" onClick={onClose}>×</button>
        </div>

        {/* Controls */}
        <div className="logs-controls">

          {/* --- NOVO FILTRO DE TEMPO --- */}
          <div className="control-group">
            <label>Tempo:</label>
            <select value={timeRange} onChange={(e) => setTimeRange(e.target.value)} className="time-select">
              <option value="all">Todo o Histórico</option>
              <option value="15m">Últimos 15 min</option>
              <option value="30m">Últimos 30 min</option>
              <option value="1h">Última 1 hora</option>
              <option value="24h">Últimas 24 horas</option>
              <option value="absolute">Personalizado</option>
            </select>
          </div>

          {/* Inputs Condicionais para Data Absoluta */}
          {timeRange === 'absolute' && (
            <div className="control-group absolute-dates">
              <input 
                type="datetime-local" 
                value={customStart} 
                onChange={(e) => setCustomStart(e.target.value)} 
                className="date-input"
              />
              <span style={{color:'white'}}>-</span>
              <input 
                type="datetime-local" 
                value={customEnd} 
                onChange={(e) => setCustomEnd(e.target.value)} 
                className="date-input"
              />
            </div>
          )}

          <div className="control-group">
            <label>Linhas:</label>
            <select value={lines} onChange={(e) => setLines(Number(e.target.value))}>
              <option value={50}>50</option>
              <option value={100}>100</option>
              <option value={200}>200</option>
              <option value={500}>500</option>
              <option value={1000}>1000</option>
            </select>
          </div>

          <div className="control-group">
            <label>Nível:</label>
            <select value={levelFilter} onChange={(e) => setLevelFilter(e.target.value)}>
              <option value="all">Todos</option>
              <option value="error">Errors</option>
              <option value="warning">Warnings</option>
              <option value="info">Info</option>
              <option value="debug">Debug</option>
            </select>
          </div>

          <div className="control-group search-group">
            <label>🔍</label>
            <input
              type="text"
              placeholder="Buscar texto..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>

          <div className="control-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={autoRefresh}
                onChange={(e) => setAutoRefresh(e.target.checked)}
              />
              Auto (3s)
            </label>
          </div>

          <button onClick={fetchLogs} className="refresh-button" disabled={loading}>
            🔄
          </button>

          <button onClick={downloadLogs} className="download-button" disabled={logs.length === 0}>
            💾
          </button>
        </div>

        {/* Error Message */}
        {error && (
          <div className="logs-error">
            ⚠️ {error}
          </div>
        )}

        {/* Stats */}
        <div className="logs-stats">
          <span>Exibindo: {logs.length} logs</span>
          {timeRange !== 'all' && <span className="filter-badge">⏳ Filtro de Tempo Ativo</span>}
          <span>Errors: {logs.filter(l => l.level === 'error').length}</span>
          <span>Warnings: {logs.filter(l => l.level === 'warning').length}</span>
          {loading && <span className="loading-indicator">⏳ Carregando...</span>}
        </div>

        {/* Logs Content */}
        <div className="logs-content">
          {logs.length === 0 ? (
            <div className="no-logs">
              {loading ? '⏳ Carregando logs...' : '📭 Nenhum log encontrado para este período/filtro.'}
            </div>
          ) : (
            logs.map((log, index) => (
              <div
                key={index}
                className={`log-entry ${getLevelColor(log.level)}`}
              >
                <div className="log-header-line">
                  <span className="log-icon">{getLevelIcon(log.level)}</span>
                  {/* Tratamento para data formatada */}
                  <span className="log-time">
                    {log.timestamp ? log.timestamp.replace('T', ' ').split('.')[0] : 'No Date'}
                  </span>
                  <span className="log-level">{log.level || 'info'}</span>

                  {/* Nome do módulo/logger */}
                  {(log.name || log.module) && (
                     <span className="log-name">[{log.module || log.name}]</span>
                  )}

                  <span className="log-function">{log.funcName ? ` ${log.funcName}()` : ''}</span>
                  <span className="log-line">{log.lineno ? `:${log.lineno}` : ''}</span>

                  <button
                    className="copy-button"
                    onClick={() => copyToClipboard(log)}
                    title="Copiar JSON"
                  >
                    📋
                  </button>
                </div>

                <div className="log-message">{log.message}</div>

                {/* Extra fields (Metadados) */}
                {Object.keys(log).filter(key => 
                  !['timestamp', 'level', 'name', 'message', 'module', 'funcName', 'lineno', 'asctime'].includes(key)
                ).length > 0 && (
                  <div className="log-extra">
                    {Object.entries(log)
                      .filter(([key]) => !['timestamp', 'level', 'name', 'message', 'module', 'funcName', 'lineno', 'asctime'].includes(key))
                      .map(([key, value]) => (
                        <span key={key} className="extra-field">
                          <strong>{key}:</strong> {typeof value === 'object' ? JSON.stringify(value) : String(value)}
                        </span>
                      ))}
                  </div>
                )}
              </div>
            ))
          )}
          <div ref={logsEndRef} />
        </div>
      </div>
    </div>
  );
};

export default LogsViewer;
